"""Stage 7: the faithful twin — plaintext model of the exact FHE circuit.

Same per-unit Chebyshev coefficients/domains the OpenFHE program will use,
same column-major packing semantics, values quantized to the CKKS scaling
grid (Δ = 2^45) at each level boundary. Validates twin vs reference (XGBoost)
and derives the application-level noise tolerance via margin analysis +
synthetic noise injection.

Also exports the C++ I/O bus: test features (standardized, box-checked),
twin logits, and the test labels.
"""
import json, sys
import numpy as np, pandas as pd
import xgboost as xgb
from sklearn.metrics import roc_auc_score, precision_recall_fscore_support

REPO = sys.argv[1] if len(sys.argv) > 1 else "."
ART = f"{REPO}/model/surrogate"; APP = f"{REPO}/data/inputs"
S = json.load(open(f"{ART}/mlp_surrogate.json"))
TH = S["threshold_logit"]; DELTA = 2.0 ** 45
fc = S["feature_cols"]
mu = np.array(S["mu"]); sd = np.array(S["sd"])
W1 = np.array(S["W1"]); b1 = np.array(S["b1"])
W2 = np.array(S["W2"]); b2 = S["b2"]
dom = list(zip(S["dom_lo"], S["dom_hi"])); coefs = S["cheb_coefs"]

q = lambda x: np.round(x * DELTA) / DELTA  # quantize to the scaling grid

te = pd.read_parquet(f"{REPO}/data/cdc_diabetes_test.parquet")
Xte = te[fc].to_numpy(np.float64); yte = te["Diabetes_binary"].to_numpy()

# client_clear: box check (survey code book) + standardize + encode-quantize
box = pd.read_csv(f"{ART}/feature_bounds.csv")
ok = np.ones(len(Xte), bool)
for i, f in enumerate(fc):
    lo, hi = box.loc[box.feature == f, ["min", "max"]].iloc[0]
    ok &= (Xte[:, i] >= lo) & (Xte[:, i] <= hi)
assert ok.all(), f"{(~ok).sum()} records outside the feature box"
Z = q((Xte - mu) / sd)                      # encoded columns (21 ciphertexts)

# server_encrypted twin: column-major, level-quantized
pre = q(Z @ W1 + b1)                        # level 1: cipher x plain MAC
hid = np.empty_like(pre)
for k in range(W1.shape[1]):                # levels 2-7: per-unit Chebyshev
    cf = np.polynomial.Chebyshev(np.array(coefs[k]), domain=list(dom[k]))
    hid[:, k] = cf(pre[:, k])
hid = q(hid)
logit_twin = q(hid @ W2 + b2)               # level 8: output MAC

# references
m = xgb.XGBClassifier(); m.load_model(f"{REPO}/model/xgb_diabetes_model.json")
p_xgb = m.predict_proba(Xte.astype(np.float32))[:, 1]
lg_xgb = np.log(p_xgb / (1 - p_xgb))
lg_exact = (1 / (1 + np.exp(-(Z @ W1 + b1))) @ W2 + b2).ravel()

def summarize(y, lg, name):
    pred = (lg >= TH).astype(int)
    pr, rc, f1, _ = precision_recall_fscore_support(y, pred, average="binary", zero_division=0)
    return {"name": name, "auc": float(roc_auc_score(y, 1/(1+np.exp(-lg)))),
            "precision": float(pr), "recall": float(rc), "f1": float(f1)}

res = {"xgb_reference": summarize(yte, lg_xgb, "xgb"),
       "surrogate_exact": summarize(yte, lg_exact, "surrogate"),
       "twin": summarize(yte, logit_twin, "twin"),
       "twin_vs_xgb_agreement": float(((logit_twin >= TH) == (lg_xgb >= TH)).mean()),
       "twin_vs_surrogate_agreement": float(((logit_twin >= TH) == (lg_exact >= TH)).mean()),
       "twin_max_err_vs_surrogate": float(np.abs(logit_twin - lg_exact).max())}

# noise tolerance: margin distribution + injection
margins = np.abs(logit_twin - TH)
res["margin"] = {"min": float(margins.min()),
                 "p01": float(np.percentile(margins, 1)),
                 "records_within_1e-3": int((margins < 1e-3).sum()),
                 "records_within_1e-4": int((margins < 1e-4).sum()),
                 "records_within_5e-5": int((margins < 5e-5).sum())}
rng = np.random.default_rng(7); inj = {}
for sigma in (5e-5, 1e-4, 1e-3, 1e-2):
    flips = [(np.sign(logit_twin + rng.normal(0, sigma, logit_twin.shape) - TH)
              != np.sign(logit_twin - TH)).sum() for _ in range(5)]
    inj[f"sigma={sigma}"] = {"mean_flips": float(np.mean(flips)),
                             "rate": float(np.mean(flips) / len(logit_twin))}
res["noise_injection"] = inj
res["noise_tolerance_stated"] = ("decision flips scale with sigma x density at "
    "threshold; at anchor noise 5e-5 expect ~%d flips / 45,895 (%.4f%%)" %
    (inj["sigma=5e-05"]["mean_flips"], 100 * inj["sigma=5e-05"]["rate"]))

json.dump(res, open(f"{ART}/twin_report.json", "w"), indent=1)

# I/O bus for the C++ pipeline (standardized features; C++ reads plain CSV)
np.savetxt(f"{APP}/test_features_std.csv", Z, delimiter=",", fmt="%.10f")
np.savetxt(f"{APP}/twin_logits.csv", logit_twin, fmt="%.10f")
np.savetxt(f"{APP}/test_labels.csv", yte, fmt="%d")
print(json.dumps(res, indent=1))
